pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 times) public {
        times = bound(times, 1, 100);
        for (uint256 i = 0; i < times; i++) {
            vm.deal(address(this), 10);
            (bool ok, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
            require(ok, "play reverted");
        }
        assertTrue(c.pot() <= address(c).balance);
    }
}
